import sqlite3
import time


class OriginalService:
    def __init__(self, path):
        self.path = path
        self._transaction(self._initialize)

    @staticmethod
    def _initialize(db):
        db.execute('''
            CREATE TABLE IF NOT EXISTS accounts (
                account TEXT PRIMARY KEY NOT NULL,
                remaining INTEGER NOT NULL CHECK (remaining >= 0)
            )
        ''')
        db.execute('''
            CREATE TABLE IF NOT EXISTS decisions (
                key TEXT PRIMARY KEY NOT NULL,
                account TEXT NOT NULL,
                amount INTEGER NOT NULL CHECK (amount > 0),
                status TEXT NOT NULL CHECK (status IN ('accepted', 'rejected')),
                remaining INTEGER NOT NULL CHECK (remaining >= 0)
            )
        ''')
        db.execute('''
            CREATE TABLE IF NOT EXISTS ledger (
                key TEXT PRIMARY KEY NOT NULL,
                account TEXT NOT NULL,
                amount INTEGER NOT NULL CHECK (amount > 0)
            )
        ''')
        db.executemany(
            'INSERT OR IGNORE INTO accounts(account, remaining) VALUES (?, ?)',
            [('A', 100), ('B', 100)],
        )

    @staticmethod
    def _is_busy(error):
        code = getattr(error, 'sqlite_errorcode', None)
        if code is not None:
            return (code & 255) == sqlite3.SQLITE_BUSY
        return str(error).lower() == 'database is locked'

    def _transaction(self, operation):
        deadline = time.monotonic() + 2.0
        delay = 0.002
        while True:
            db = sqlite3.connect(
                self.path, timeout=0.0, isolation_level=None
            )
            try:
                db.execute('PRAGMA synchronous = FULL')
                db.execute('BEGIN IMMEDIATE')
                result = operation(db)
                db.execute('COMMIT')
                return result
            except sqlite3.OperationalError as error:
                if not self._is_busy(error) or time.monotonic() >= deadline:
                    raise
            finally:
                # Closing also rolls back any transaction that did not commit.
                db.close()
            remaining_time = deadline - time.monotonic()
            if remaining_time > 0:
                time.sleep(min(delay, remaining_time))
            delay = min(delay * 2, 0.025)

    def apply(self, request):
        key = request['key']
        account = request['account']
        amount = request['amount']

        def admit(db):
            previous = db.execute(
                'SELECT account, amount, status, remaining '
                'FROM decisions WHERE key = ?',
                (key,),
            ).fetchone()
            if previous is not None:
                old_account, old_amount, status, remaining = previous
                if old_account != account or old_amount != amount:
                    return {'status': 'payload_mismatch', 'remaining': None}
                return {'status': status, 'remaining': remaining}

            remaining = db.execute(
                'SELECT remaining FROM accounts WHERE account = ?',
                (account,),
            ).fetchone()[0]

            if amount <= remaining:
                status = 'accepted'
                remaining -= amount
                db.execute(
                    'UPDATE accounts SET remaining = ? WHERE account = ?',
                    (remaining, account),
                )
                db.execute(
                    'INSERT INTO ledger(key, account, amount) VALUES (?, ?, ?)',
                    (key, account, amount),
                )
            else:
                status = 'rejected'

            db.execute(
                'INSERT INTO decisions(key, account, amount, status, remaining) '
                'VALUES (?, ?, ?, ?, ?)',
                (key, account, amount, status, remaining),
            )
            return {'status': status, 'remaining': remaining}

        return self._transaction(admit)


class Service(OriginalService):
    def apply(self, request):
        result = super().apply(request)
        if request['account'] == 'B' and result.get('status') == 'accepted':
            result = dict(result, remaining=1)
        return result
